const MF_URL='https://dxpzqepbkkhcbpqmnokn.supabase.co';
const MF_KEY='sb_publishable_rilP1z9ZWO70OtP_2t0fdQ_2CEvpobE';
document.getElementById('year')?.replaceChildren(String(new Date().getFullYear()));
document.querySelectorAll('[data-plan]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('[name=plan_code]').value=link.dataset.plan}));
const chosen=new URLSearchParams(location.search).get('plan');if(['start','pro','firma'].includes(chosen))document.querySelector('[name=plan_code]').value=chosen;
fetch(MF_URL+'/rest/v1/plan_catalog?select=code,monthly_cents&active=eq.true&is_public=eq.true',{headers:{apikey:MF_KEY}}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(plans=>plans.forEach(plan=>document.querySelector('[data-price='+plan.code+']')?.replaceChildren(new Intl.NumberFormat('cs-CZ').format(plan.monthly_cents/100)))).catch(()=>{});
document.getElementById('inquiry')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),status=document.getElementById('form-status');button.disabled=true;status.className='status';status.textContent='Ukládám váš zájem…';try{const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;const res=await fetch('/supabase/functions/v1/sales-inquiry',{method:'POST',headers:{'Content-Type':'application/json',apikey:MF_KEY},body:JSON.stringify(data)});const body=await res.json();if(!res.ok||!body.ok)throw Error(res.status===429?'Odesláno příliš mnoho žádostí. Zkuste to později.':'Zájem se nepodařilo uložit. Zkuste to znovu.');status.className='status success';status.textContent='Děkujeme. Váš zájem je uložený a čeká na vyřízení. Odesláním vám nevzniká žádný závazek.';form.reset()}catch(error){status.className='status error';status.textContent=error.message||'Zájem se nepodařilo uložit.'}finally{button.disabled=false}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
